const footer =
  '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:ftr xmlns:w="' +
  W +
  '">' +
  '<w:p><w:pPr><w:jc w:val="center"/></w:pPr>' +
  '<w:r><w:fldChar w:fldCharType="begin"/></w:r>' +
  '<w:r><w:instrText xml:space="preserve"> PAGE </w:instrText></w:r>' +
  '<w:r><w:fldChar w:fldCharType="separate"/></w:r>' +
  '<w:r><w:t>1</w:t></w:r>' +
  '<w:r><w:fldChar w:fldCharType="end"/></w:r></w:p></w:ftr>';

const numbering =
  '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:numbering xmlns:w="' +
  W +
  '">' +
  '<w:abstractNum w:abstractNumId="0"><w:lvl w:ilvl="0"><w:start w:val="1"/>' +
  '<w:numFmt w:val="bullet"/><w:lvlText w:val="•"/><w:lvlJc w:val="left"/>' +
  '<w:pPr><w:ind w:left="720" w:hanging="360"/></w:pPr></w:lvl></w:abstractNum>' +
  '<w:num w:numId="1"><w:abstractNumId w:val="0"/></w:num></w:numbering>';

const headingStyle = (id, name, lvl, before, after, jc) =>
  '<w:style w:type="paragraph" w:styleId="' + id + '"><w:name w:val="' + name + '"/>' +
  '<w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:qFormat/>' +
  '<w:pPr><w:keepNext/><w:spacing w:before="' + before + '" w:after="' + after + '"/>' +
  '<w:jc w:val="' + jc + '"/><w:outlineLvl w:val="' + lvl + '"/></w:pPr>' +
  '<w:rPr><w:b/><w:bCs/></w:rPr></w:style>';

const styles =
  '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="' +
  W +
  '">' +
  '<w:docDefaults><w:rPrDefault><w:rPr>' +
  '<w:rFonts w:ascii="' + FONT + '" w:eastAsia="' + FONT + '" w:hAnsi="' + FONT + '" w:cs="' + FONT + '"/>' +
  '<w:sz w:val="' + SZ + '"/><w:szCs w:val="' + SZ + '"/><w:color w:val="000000"/>' +
  '</w:rPr></w:rPrDefault><w:pPrDefault><w:pPr>' +
  '<w:spacing w:after="120" w:line="' + LINE_BODY + '" w:lineRule="auto"/>' +
  '<w:jc w:val="both"/></w:pPr></w:pPrDefault></w:docDefaults>' +
  '<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/><w:qFormat/></w:style>' +
  headingStyle('Heading1', 'heading 1', '0', '240', '200', 'center') +
  headingStyle('Heading2', 'heading 2', '1', '200', '160', 'left') +
  headingStyle('Heading3', 'heading 3', '2', '160', '120', 'left') +
  '</w:styles>';

const settings =
  '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:settings xmlns:w="' +
  W +
  '">' +
  '<w:updateFields w:val="true"/><w:defaultTabStop w:val="720"/></w:settings>';

const pgMar =
  '<w:pgMar w:top="' + MARGIN.top + '" w:right="' + MARGIN.right +
  '" w:bottom="' + MARGIN.bottom + '" w:left="' + MARGIN.left +
  '" w:header="708" w:footer="708" w:gutter="0"/>';
const pgSz = '<w:pgSz w:w="' + PAGE.w + '" w:h="' + PAGE.h + '"/>';

const documentXml =
  '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
  '<w:document xmlns:w="' + W + '" xmlns:r="' + R + '"><w:body>' +
  sec1 +
  // Section 1 closes here: roman numerals, cover page unnumbered.
  '<w:p><w:pPr><w:sectPr>' +
  '<w:footerReference w:type="default" r:id="rId4"/>' + pgSz + pgMar +
  '<w:pgNumType w:fmt="lowerRoman" w:start="1"/><w:titlePg/>' +
  '</w:sectPr></w:pPr></w:p>' +
  sec2 +
  // Section 2: arabic numerals, restarting at 1.
  '<w:sectPr><w:footerReference w:type="default" r:id="rId5"/>' + pgSz + pgMar +
  '<w:pgNumType w:fmt="decimal" w:start="1"/></w:sectPr>' +
  '</w:body></w:document>';

// ------------------------------------------------------------------ output ----
const zip = createZip([
  { name: '[Content_Types].xml', content: contentTypes },
  { name: '_rels/.rels', content: rootRels },
  { name: 'word/_rels/document.xml.rels', content: docRels },
  { name: 'word/document.xml', content: documentXml },
  { name: 'word/styles.xml', content: styles },
  { name: 'word/settings.xml', content: settings },
  { name: 'word/numbering.xml', content: numbering },
  { name: 'word/footer1.xml', content: footer },
  { name: 'word/footer2.xml', content: footer },
]);

const safe = String(meta.student_name || 'Thesis').replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '');
const filename = safe + '_Thesis_Proposal.docx';

return [
  {
    json: {
      filename: filename,
      size_bytes: zip.length,
      tables_listed: tables.length,
      figures_listed: figures.length,
      abbreviations_listed: abbrs.length,
      references_rendered: references.length,
    },
    binary: {
      data: {
        data: zip.toString('base64'),
        mimeType: MIME + '.document',
        fileName: filename,
        fileExtension: 'docx',
      },
    },
  },
];
